dtsPropsFor.Bump:
/** The number (or short text) to show. A change replays the drop-in; the first render never animates. */
value: number | string;
/** Optional custom content in place of `value` (still keyed on `value`). */
children?: React.ReactNode;
style?: React.CSSProperties;

dtsPropsFor.ErrorBanner:
/** The message to show, verbatim. Nothing renders when it is empty. Network failures ("Failed to fetch") are reworded into what to do. */
message?: string | null;
style?: React.CSSProperties;

dtsPropsFor.Modal:
/** id of the heading inside the dialog, for aria-labelledby. */
labelledBy: string;
/** Called on Escape and on a backdrop click. */
onClose: () => void;
/** Styles for the panel: the app passes a cream card, e.g. { background: '#F7F5EF', color: '#1B1B1B', borderRadius: 14, padding: '1.5rem' }. */
panelStyle?: React.CSSProperties;
children?: React.ReactNode;

dtsPropsFor.ScoringControls:
/** True while someone else holds the scorer lock: every control inside is disabled and dimmed. */
locked?: boolean;
children?: React.ReactNode;

